// Typed fetch client for the FastAPI backend. Response types come from
// lib/api-types.ts, generated by `make types` from FastAPI's /openapi.json.

import type { components } from "@/lib/api-types";

export const API_URL = (process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000").replace(
  /\/+$/,
  "",
);

/** A failed request. `status` 0 means the API could not be reached at all. */
export class ApiError extends Error {
  constructor(
    public status: number,
    public body: unknown,
  ) {
    super(
      status === 0 ? `Cannot reach the API at ${API_URL}` : `API request failed with status ${status}`,
    );
    this.name = "ApiError";
  }
}

export function apiUrl(path: string): string {
  return `${API_URL}${path.startsWith("/") ? path : `/${path}`}`;
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(apiUrl(path), {
      ...init,
      headers: { "Content-Type": "application/json", ...init?.headers },
    });
  } catch {
    // fetch only rejects when no response arrived: API down, wrong URL or CORS.
    throw new ApiError(0, null);
  }
  const text = await res.text();
  let body: unknown = null;
  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    body = text; // e.g. a plain-text "Internal Server Error"
  }
  if (!res.ok) throw new ApiError(res.status, body);
  return body as T;
}

/** What to tell the user about a failed request: the API's own message when it sent one,
 *  a hint to start the API when it is unreachable, otherwise `fallback`. */
export function errorMessage(err: unknown, fallback: string): string {
  if (!(err instanceof ApiError)) return fallback;
  if (err.status === 0) {
    return `Cannot reach the API at ${API_URL}. Is it running? Start it with "make api".`;
  }
  const detail = (err.body as { detail?: unknown } | null)?.detail;
  if (typeof detail === "string" && detail) return detail;
  if (detail && typeof (detail as { message?: unknown }).message === "string") {
    return (detail as { message: string }).message;
  }
  if (Array.isArray(detail)) {
    const msgs = detail
      .map((d) => (d as { msg?: unknown })?.msg)
      .filter((m): m is string => typeof m === "string" && m !== "");
    if (msgs.length) return msgs.join(". ");
  }
  return `${fallback} (HTTP ${err.status})`;
}

export type Schemas = components["schemas"];
export type Health = Schemas["HealthResponse"];
export type CatalogItem = Schemas["CatalogItem"];
export type CatalogRegion = Schemas["CatalogRegion"];
export type Experiment = Schemas["Experiment"];
export type ExperimentCreate = Schemas["ExperimentCreate"];
export type ExperimentUpdate = Schemas["ExperimentUpdate"];
export type ExperimentItem = Schemas["ExperimentItem"];
export type ItemRef = Schemas["ItemRef"];
export type Split = Schemas["Split"];
export type Run = Schemas["Run"];
export type RunCreate = Schemas["RunCreate"];
export type RunStatus = Run["status"];
export type CebraSchema = Schemas["CebraSchema"];

export type CatalogQuery = {
  region?: string[];
  subject?: string;
  lab?: string;
  min_units?: number;
  limit?: number;
  offset?: number;
};

/** Build a query string; arrays become repeated keys, empty values are dropped. */
export function toQuery(params: Record<string, string | number | string[] | undefined>): string {
  const sp = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === "") continue;
    for (const v of Array.isArray(value) ? value : [value]) sp.append(key, String(v));
  }
  const qs = sp.toString();
  return qs ? `?${qs}` : "";
}

export const api = {
  health: () => apiFetch<Health>("/api/health"),
  catalogItems: (q: CatalogQuery = {}) =>
    apiFetch<CatalogItem[]>(`/api/catalog/items${toQuery(q)}`),
  catalogRegions: () => apiFetch<CatalogRegion[]>("/api/catalog/regions"),
  cebraSchema: () => apiFetch<CebraSchema>("/api/cebra/schema"),
  experiments: {
    list: () => apiFetch<Experiment[]>("/api/experiments"),
    get: (id: string) => apiFetch<Experiment>(`/api/experiments/${encodeURIComponent(id)}`),
    create: (body: ExperimentCreate) =>
      apiFetch<Experiment>("/api/experiments", { method: "POST", body: JSON.stringify(body) }),
    update: (id: string, body: ExperimentUpdate) =>
      apiFetch<Experiment>(`/api/experiments/${encodeURIComponent(id)}`, {
        method: "PATCH",
        body: JSON.stringify(body),
      }),
    items: (id: string) =>
      apiFetch<ExperimentItem[]>(`/api/experiments/${encodeURIComponent(id)}/items`),
    replaceItems: (id: string, items: ItemRef[]) =>
      apiFetch<ExperimentItem[]>(`/api/experiments/${encodeURIComponent(id)}/items`, {
        method: "PUT",
        body: JSON.stringify({ items }),
      }),
    reshuffle: (id: string, eid: string) =>
      apiFetch<Split>(
        `/api/experiments/${encodeURIComponent(id)}/splits/${encodeURIComponent(eid)}/reshuffle`,
        { method: "POST" },
      ),
    runs: (id: string) => apiFetch<Run[]>(`/api/experiments/${encodeURIComponent(id)}/runs`),
    createRun: (id: string, body: RunCreate) =>
      apiFetch<Run>(`/api/experiments/${encodeURIComponent(id)}/runs`, {
        method: "POST",
        body: JSON.stringify(body),
      }),
  },
};

/** TanStack Query keys, shared so mutations can invalidate the right caches. */
export const queryKeys = {
  experiments: ["experiments"] as const,
  experiment: (id: string) => ["experiments", id] as const,
  /** Under `experiment(id)`, so invalidating the experiment also refetches its items. */
  items: (id: string) => ["experiments", id, "items"] as const,
  catalogItems: (q: CatalogQuery) => ["catalog", "items", q] as const,
  catalogRegions: ["catalog", "regions"] as const,
  /** Under `experiment(id)`, like items. */
  runs: (id: string) => ["experiments", id, "runs"] as const,
  cebraSchema: ["cebra", "schema"] as const,
};
